fn constant(x:&N,n:usize)->B{trim((0..n).map(|i|u32::from(x.bit(i as u64))).collect())}
fn red(a:&mut A,x:&B,m:&Model)->B{let n=m.c.n;let mut v=x.clone();for i in (n..v.len()).rev(){let t=v[i];v[i]=0;for j in 0..n{if m.c.modulus.bit(j as u64){v[i-n+j]=a.xor(v[i-n+j],t);}}}v.truncate(n);trim(v)}
fn fm(a:&mut A,x:&B,y:&B,m:&Model)->B{let p=mul(a,x,y);red(a,&p,m)}
fn fsq(a:&mut A,x:&B,m:&Model)->B{if x.is_empty(){return vec![];}let mut v=vec![0;2*x.len()-1];for(i,t)in x.iter().enumerate(){v[2*i]=*t;}red(a,&v,m)}
fn lin(a:&mut A,cols:&[N],x:&B,n:usize)->B{let mut v=vec![0;n];for(i,t)in x.iter().enumerate(){if *t==0{continue;}for(j,w)in v.iter_mut().enumerate(){if cols[i].bit(j as u64){*w=a.xor(*w,*t);}}}trim(v)}
fn mc(a:&mut A,value:&N,x:&B,m:&Model)->B{if value.is_zero(){return vec![];}if *value==N::one(){return x.clone();}let cols=(0..m.c.n).map(|i|m.c.mul(&(N::one()<<i),value)).collect::<Vec<_>>();lin(a,&cols,x,m.c.n)}
fn sum(a:&mut A,vs:&[B])->B{vs.iter().fold(vec![],|x,y|add(a,&x,y))}
fn build(m:&Model,d:usize,cutoff:usize)->(A,Vec<u32>){let mut a=A::new();a.cutoff=cutoff;let xs=(0..5).map(|_|(0..d).map(|_|a.input()).collect::<B>()).collect::<Vec<_>>();let r=(0..m.c.n).map(|_|a.input()).collect::<B>();let sigma=a.input();let mut p=vec![vec![1]];for root in xs{let mut out=vec![vec![];p.len()+1];for(j,c)in p.iter().enumerate(){let q=mul(&mut a,c,&root);out[j]=add(&mut a,&out[j],&q);out[j+1]=add(&mut a,&out[j+1],c);}p=out;}let hc=p[..5].iter().map(|x|red(&mut a,x,m)).collect::<Vec<_>>();let h0=lin(&mut a,&m.as_cols,&hc[4],m.c.n);let mut h=add(&mut a,&h0,&constant(&m.as_z,m.c.n));if h.is_empty(){h.push(0);}h[0]=a.xor(h[0],sigma);let residual=lin(&mut a,&m.as_res,&hc[4],m.c.n);let mut eq=add(&mut a,&residual,&constant(&m.res_z,m.c.n));let r2=fsq(&mut a,&r,m);let hr=fm(&mut a,&h,&r,m);let ah2=if m.a.is_zero(){vec![]}else{let h2=fsq(&mut a,&h,m);mc(&mut a,&m.a,&h2,m)};let ze1=mc(&mut a,&m.z,&hc[4],m);let k=sum(&mut a,&[hc[3].clone(),r2,hr,ah2,ze1]);let w=lin(&mut a,&m.w_cols,&hc[0],m.c.n);let zr=mc(&mut a,&m.z,&r,m);let ck=mc(&mut a,&m.cval,&k,m);let yh=mc(&mut a,&m.yt,&h,m);let s=sum(&mut a,&[zr,ck,yh,constant(&m.c.sq(&m.z),m.c.n),w.clone()]);let hs=fm(&mut a,&h,&s,m);let kr=fm(&mut a,&k,&r,m);let k2=fsq(&mut a,&k,m);let ze2=mc(&mut a,&m.z,&hc[3],m);let third=sum(&mut a,&[hc[2].clone(),hs,kr,k2.clone(),ze2]);let bk2=mc(&mut a,&m.beta,&k2,m);let zw=mc(&mut a,&m.z,&w,m);let zwk=fm(&mut a,&zw,&k,m);let ze4=mc(&mut a,&m.z,&hc[1],m);let fourth=sum(&mut a,&[bk2,zwk,hc[0].clone(),ze4]);eq.extend(third);eq.extend(fourth);(a,eq)}

fn hx(x:&str)->N{N::parse_bytes(x.trim_start_matches("0x").as_bytes(),16).unwrap()}
fn norm_controls()->Value{let mut checks=0;let mut accepted=0;let mut models=0;for(n,modulus,d)in[(2,7,1),(3,11,2),(4,19,1)]{let ctx=numeric::C::new(n,N::from(modulus as u32));let mut configs=vec![(N::zero(),N::zero()),(N::zero(),N::one())];if let Some(y)=(0..1usize<<n).map(N::from).find(|y|(ctx.sq(y)^y)==N::one()){configs.push((N::one(),y));}for(ca,yt)in configs{let m=Model::new(n,N::from(modulus as u32),ca,N::one(),N::one(),yt);models+=1;for cutoff in [0,8]{let(a,eq)=build(&m,d,cutoff);let count=1usize<<a.inputs;assert!(count<=16384);for mask in 0..count{let input=(0..a.inputs).map(|i|(mask>>i)&1!=0).collect::<Vec<_>>();let xs=(0..5).map(|i|N::from(((mask>>(i*d))&((1<<d)-1))as u32)).collect::<Vec<_>>();let r=N::from(((mask>>(5*d))&((1<<n)-1))as u32);let sigma=(mask>>(5*d+n))&1!=0;let hc=m.c.product(&xs);let(h,k,s,trace)=m.recover(&hc,&r,sigma);let actual=m.c.literal(&h,&k,&r,&s,&m.a,&m.b,&m.z,&m.yt);let want=trace&&actual==hc;assert_eq!(a.eval(&input,&eq),want,"n{n} mask{mask}");if want{accepted+=1;}checks+=1;}}}}json!({"status":"passed","independent_full_norm_assignments":checks,"models":models,"accepted_assignments_across_arms":accepted,"oracle":"literal curve norm / (X+z), both target signs, a0/a1 where rational, and complete small primary assignments; not eliminated residual formulas"})}
fn active(a:&A,eq:&[u32])->Vec<bool>{let mut keep=vec![false;a.nodes.len()];let mut stack=eq.to_vec();while let Some(i)=stack.pop(){if keep[i as usize]{continue;}keep[i as usize]=true;let node=a.nodes[i as usize];if node[0]>=2{stack.push(node[1]);stack.push(node[2]);}}keep}
fn forms(a:&A,keep:&[bool])->(Vec<N>,Vec<Option<usize>>,usize){let mut out=vec![N::zero();a.nodes.len()];out[1]=N::one();let mut atom=vec![None;a.nodes.len()];let mut nonlinear=0;for(i,node)in a.nodes.iter().enumerate().skip(2){if node[0]==1{let j=node[1]as usize+1;out[i]=N::one()<<j;atom[i]=Some(j);}else if keep[i]{if node[0]==3{let j=1+a.inputs+nonlinear;out[i]=N::one()<<j;atom[i]=Some(j);nonlinear+=1;}else{out[i]=&out[node[1]as usize]^&out[node[2]as usize];}}}(out,atom,nonlinear)}
fn bits(x:&N)->Vec<usize>{let mut out=vec![];for(i,w)in x.to_u64_digits().iter().enumerate(){let mut w=*w;while w!=0{let b=w.trailing_zeros()as usize;out.push(64*i+b);w&=w-1;}}out}
struct UF{p:Vec<usize>,n:Vec<usize>}
impl UF{fn new(n:usize)->Self{Self{p:(0..n).collect(),n:vec![1;n]}}fn root(&mut self,mut i:usize)->usize{while self.p[i]!=i{self.p[i]=self.p[self.p[i]];i=self.p[i];}i}fn join(&mut self,x:usize,y:usize){let mut x=self.root(x);let mut y=self.root(y);if x==y{return;}if self.n[x]<self.n[y]{std::mem::swap(&mut x,&mut y);}self.p[y]=x;self.n[x]+=self.n[y];}}
fn components(n:usize,rows:&[Vec<usize>])->(usize,usize){let mut uf=UF::new(n);let mut live=vec![false;n];for row in rows{if let Some(first)=row.first(){for v in row{live[*v]=true;uf.join(*first,*v);}}}let mut cols=vec![0usize;n];let mut count=vec![0usize;n];for(i,v)in live.iter().enumerate(){if *v{let r=uf.root(i);cols[r]+=1;}}for row in rows{if let Some(v)=row.first(){let r=uf.root(*v);count[r]+=1;}}(count.into_iter().max().unwrap_or(0),cols.into_iter().max().unwrap_or(0))}
fn profile(a:&A,eq:&[u32])->Value{let keep=active(a,eq);let(fs,_,nonlinear)=forms(a,&keep);let mut defs=std::collections::BTreeSet::new();for(i,node)in a.nodes.iter().enumerate(){if keep[i]&&node[0]==3{for wire in [node[1],node[2]]{let value=&fs[wire as usize]>>1;if bits(&value).len()>1{defs.insert(value);}}}}let base=a.inputs+nonlinear;let mut rows=vec![];let mut contradictions=0usize;let mut maxarity=0;let mut nonzeros=0;for(i,form)in defs.iter().enumerate(){let mut row=bits(form);row.push(base+i);maxarity=maxarity.max(row.len());nonzeros+=row.len();rows.push(row);}for wire in eq{let row=bits(&(&fs[*wire as usize]>>1));if row.is_empty()&&fs[*wire as usize].bit(0){contradictions+=1;}maxarity=maxarity.max(row.len());nonzeros+=row.len();if !row.is_empty(){rows.push(row);}}let compressed=components(base+defs.len(),&rows);let mut original=vec![];let mut fixed=vec![false;a.nodes.len()];fixed[0]=true;fixed[1]=true;for wire in eq{fixed[*wire as usize]=true;}for(i,node)in a.nodes.iter().enumerate(){if keep[i]&&node[0]==2{let row=[i,node[1]as usize,node[2]as usize].into_iter().filter(|i|!fixed[*i]).collect::<Vec<_>>();if !row.is_empty(){original.push(row);}}}let old=components(a.nodes.len(),&original);json!({"primary_variables":a.inputs,"nonlinear_and_atoms":nonlinear,"affine_input_definitions":defs.len(),"compressed_variables":base+defs.len(),"compressed_xor_rows":rows.len(),"compressed_max_component_rows":compressed.0,"compressed_max_component_columns":compressed.1,"longest_xor_row":maxarity,"xor_nonzero_coefficients":nonzeros,"old_preprop_component_rows":old.0,"old_preprop_component_columns":old.1,"old_component_scope":"after explicit constant/output units, before further native unit propagation or row simplification","long_xor_interface_required":maxarity>3,"constant_contradictions":contradictions,"formal_matrix_caps_admitted":compressed.0<=16384&&compressed.1<=32768})}
fn controls()->Value{let mut result=norm_controls();let m=Model::new(3,N::from(11u32),N::zero(),N::one(),N::one(),N::zero());let(a,eq)=build(&m,2,8);let keep=active(&a,&eq);let(fs,atom,_)=forms(&a,&keep);let mut checks=0;for mask in 0..1usize<<a.inputs{let inputs=(0..a.inputs).map(|i|mask>>i&1!=0).collect::<Vec<_>>();let mut values=vec![false;a.nodes.len()];values[1]=true;for(i,node)in a.nodes.iter().enumerate().skip(2){values[i]=match node[0]{1=>inputs[node[1]as usize],2=>values[node[1]as usize]^values[node[2]as usize],3=>values[node[1]as usize]&values[node[2]as usize],_=>panic!()};}let mut assignment=N::one();for(i,bit)in atom.iter().enumerate(){if let Some(j)=bit{if values[i]{assignment|=N::one()<<j;}}}for(i,value)in fs.iter().enumerate(){if keep[i]{let parity=(&assignment&value).to_u64_digits().iter().map(|x|x.count_ones()).sum::<u32>()%2!=0;assert_eq!(parity,values[i]);}}checks+=1;}result["affine_cone_complete_primary_assignments"]=json!(checks);result}
fn run(id:&str,path:&str)->Value{let input:Value=serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();let n=input["extension_field"]["degree"].as_u64().unwrap()as usize;assert_eq!(n,83);let z=hx(input["target"]["x_hex"].as_str().unwrap());let yt=hx(input["target"]["y_hex"].as_str().unwrap())^&z;let m=Model::new(n,hx(input["extension_field"]["modulus_hex"].as_str().unwrap()),hx(input["curve"]["a_hex"].as_str().unwrap()),hx(input["curve"]["b_hex"].as_str().unwrap()),z,yt);let basis=input["source_basis_hex"].as_array().unwrap();assert_eq!(basis.len(),18);for(i,b)in basis.iter().enumerate(){assert_eq!(hx(b.as_str().unwrap()),N::one()<<i);}assert!(hx(input["source_offset_hex"].as_str().unwrap_or("0x0")).is_zero());let start=Instant::now();let(a,eq)=build(&m,18,8);let e=profile(&a,&eq);assert!(start.elapsed().as_secs()<65);json!({"schema":"scientific_result_v1","experiment_id":id,"status":"passed","summary":"Exact affine-cone substitution profiles a smaller long-XOR interface for the complete binary norm predicate.","evidence":{"profile":e,"scope":"exact circuit representation and component-bound profile, not a SAT solve or native matrix admission","original_root_count_exact":null,"release_gate_claim":false,"novelty_claim":false,"profile_complete":true},"next_actions":["If formal component caps pass, implement a source-pinned long-XOR native interface and rerun exhaustive tiny model-set controls before any hard search.","If caps fail, change representation instead of assuming higher memory or retrying unchanged.","Retain global original S3/ghost/auxiliary-fiber coverage and matched8x gate."]})}
